import math
    import random
    import time

    LANGUAGE_WRAPPER = "A rectangle is subdivided by drawing some number of full-length vertical lines and some number of full-length horizontal lines, all parallel to the rectangle's sides, producing a rectangular grid with exactly {n} small rectangles (i.e., there exist nonnegative integers v,h with (v+1)(h+1)={n}). Nodes are the grid intersections and fundamental line segments are the minimal side segments of the grid between consecutive nodes. Let H be the number of horizontal fundamental segments and V be the number of vertical fundamental segments. For given positive integers {w_h} and {w_v}, define W = {w_h}·H + {w_v}·V. Among all such grid subdivisions producing exactly {n} small rectangles, determine the sum of the maximum possible value of W and the minimum possible value of W."

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose a and b to define n=a*b with moderate size and nontrivial factorization
# Ensure a and b are at least 6 to avoid trivial tiny cases and keep difficulty
while True:
    a = rng.randint(6, 60)
    b = rng.randint(6, 60)
    n = a * b
    if n >= 100:  # ensure sufficiently large
        break
# Choose distinct weights for extra asymmetry and difficulty
w_choices = list(range(2, 10))
rng.shuffle(w_choices)
w_h = w_choices[0]
w_v = w_choices[1]
# Return assignment
return {'n': n, 'w_h': w_h, 'w_v': w_v}

    def verifier(assign):
# Validate assignment
try:
    n = int(assign['n'])
    w_h = int(assign['w_h'])
    w_v = int(assign['w_v'])
except Exception:
    # Missing or invalid types
    return (False, None)
if n <= 1 or w_h <= 0 or w_v <= 0:
    # Domain constraints violated
    return (False, None)
# Compute all divisors d of n
divs = []
d = 1
while d * d <= n:
    if n % d == 0:
        divs.append(d)
        if d * d != n:
            divs.append(n // d)
    d += 1
if len(divs) < 4:
    # Enforce nontriviality: n should have multiple factor pairs (at least 2 nontrivial divisors)
    # This keeps the optimization nontrivial.
    return (False, None)
# For a grid with a=v+1, b=h+1, ab=n, we have:
# H = a(b+1), V = b(a+1), hence W = (w_h + w_v) n + w_h a + w_v b.
# Extremize over integer factor pairs (a,b) with ab=n.
base = (w_h + w_v) * n
min_term = None
max_term = None
for a in divs:
    b = n // a
    term = w_h * a + w_v * b
    if (min_term is None) or (term < min_term):
        min_term = term
    if (max_term is None) or (term > max_term):
        max_term = term
if min_term is None or max_term is None:
    return (False, None)
W_min = base + min_term
W_max = base + max_term
answer = W_min + W_max
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

